        .stats-table tr:hover { background: #f7fafc; }
        .insight-box { background: linear-gradient(135deg, #f0f4f8 0%, #e2e8f0 100%); border-radius: 8px; padding: 20px; margin: 15px 0; }
        .insight-box h4 { color: #2d3748; margin-bottom: 10px; }
        .decade-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 15px; margin: 20px 0; }
        .decade-card { background: #f7fafc; border-radius: 8px; padding: 20px; text-align: center; }
        .decade-card .decade { font-size: 1.2em; font-weight: 700; color: #2d3748; }
        .decade-card .avg { font-size: 1.4em; color: #3182ce; font-weight: 700; margin: 5px 0; }
        .decade-card .range { font-size: 0.85em; color: #718096; }
        .tag { display: inline-block; padding: 4px 10px; border-radius: 4px; font-size: 0.8em; font-weight: 600; margin: 2px; }
